\begin{lemma}
\label{lem:6.1}
($\mathbb{R}^n$ is a vector space over $\mathbb{R}$) Let $n\in\mathbb{N}$. For $x=(x_1,\dots,x_n),y=(y_1,\dots,y_n)\in\mathbb{R}^n$ define
\[
\label{eq:6.u6}
x+y:=(x_1+y_1,\dots,x_n+y_n),\qquad 0:=(0,\dots,0),\qquad -x:=(-x_1,\dots,-x_n),
\]
and for $c\in\mathbb{R}$ define
\[
\label{eq:6.u7}
cx:=(cx_1,\dots,cx_n).
\]
Then for all $x,y,z\in\mathbb{R}^n$ and all $c,d\in\mathbb{R}$ the following identities hold:
\begin{align*}
\label{eq:6.u5}
&x+y=y+x,\\
&(x+y)+z=x+(y+z),\\
&x+0=0+x=x,\\
&x+(-x)=(-x)+x=0,\\
&(cd)x=c(dx),\\
&c(x+y)=cx+cy,\\
&(c+d)x=cx+dx,\\
&1x=x.
\end{align*}
\end{lemma}

\begin{definition}
\label{def:6.2}
[Transpose]
Let $n\in\mathbb{N}$ and let $(x_i)_{1\le i\le n}=(x_1,x_2,\ldots,x_n)$ be an $n$-dimensional row vector. The \emph{transpose} of $(x_i)_{1\le i\le n}$ is the $n\times 1$ column vector defined by
\[
\label{eq:6.u16}
(x_i)_{1\le i\le n}^T=(x_1,x_2,\ldots,x_n)^T:=\begin{pmatrix}x_1\\x_2\\\vdots\\x_n\end{pmatrix}.
\]
An \emph{$n$-dimensional column vector} is a vector of the form $(x_i)_{1\le i\le n}^T$ for some $n$-dimensional row vector $(x_i)_{1\le i\le n}$.
\end{definition}

\begin{definition}
\label{def:6.3}
[Standard basis vectors of $\mathbb{R}^n$]
Let $n\ge 1$ be an integer. For each $j\in\{1,\dots,n\}$, the \emph{standard basis (row) vector} $e_j\in\mathbb{R}^n$ is defined by
\[
\label{eq:6.u17}
(e_j)_i = \begin{cases}1,& i=j,\\0,& i\ne j,\end{cases}\qquad 1\le i\le n.
\]
Then for every $x=(x_1,\dots,x_n)\in\mathbb{R}^n$,
\[
\label{eq:6.u18}
x=\sum_{j=1}^n x_j e_j.
\]
Viewing $x^T$ as a column vector, one also has
\[
\label{eq:6.u19}
x^T=\sum_{j=1}^n x_j e_j^T.
\]
\end{definition}

\begin{definition}
\label{def:6.4}
[Linear transformation]
A function $T:\mathbb{R}^n\to\mathbb{R}^m$ is a \emph{linear transformation} if, for all $x,y\in\mathbb{R}^n$ and all scalars $c\in\mathbb{R}$, the following hold:
\begin{enumerate}
\item (Additivity) $T(x+y)=T(x)+T(y)$.
\item (Homogeneity) $T(cx)=c\,T(x)$.
\end{enumerate}
\end{definition}

\begin{proposition}
\label{prop:6.1}
The map $T_1:\mathbb{R}^3\to\mathbb{R}^3$ defined by $T_1x:=5x$ is a linear transformation.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:6.1}
For all $x,x'\in\mathbb{R}^3$, $T_1(x+x')=5(x+x')=5x+5x'=T_1x+T_1x'$. For all $x\in\mathbb{R}^3$ and $c\in\mathbb{R}$, $T_1(cx)=5(cx)=c(5x)=c\,T_1x$. Hence $T_1$ is linear.
\end{proof}

