\begin{proposition}
\label{prop:6.2}
Let $T_2:\mathbb{R}^2\to\mathbb{R}^2$ be the map that rotates each vector in $\mathbb{R}^2$ about the origin by angle $\pi/2$ counterclockwise. Then $T_2$ is a linear transformation.
\end{proposition}

\begin{proposition}
\label{prop:6.3}
Define $T_3:\mathbb{R}^3\to\mathbb{R}^2$ by $T_3(x,y,z)=(x,y)$. Then $T_3$ is a linear transformation; that is, for all $u,v\in\mathbb{R}^3$ and all scalars $c\in\mathbb{R}$, one has $T_3(u+v)=T_3(u)+T_3(v)$ and $T_3(cu)=c\,T_3(u)$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:6.3}
Let $u=(x_1,y_1,z_1)$ and $v=(x_2,y_2,z_2)$ be elements of $\mathbb{R}^3$, and let $c\in\mathbb{R}$.
Then
\[
\label{eq:6.u24}
T_3(u+v)=T_3(x_1+x_2,\,y_1+y_2,\,z_1+z_2)=(x_1+x_2,\,y_1+y_2)
=(x_1,y_1)+(x_2,y_2)=T_3(u)+T_3(v).
\]
Also,
\[
\label{eq:6.u25}
T_3(cu)=T_3(cx_1,\,cy_1,\,cz_1)=(cx_1,\,cy_1)=c(x_1,y_1)=c\,T_3(u).
\]
Thus $T_3$ preserves addition and scalar multiplication, so it is linear.
\end{proof}

