\begin{proposition}
\label{prop:6.4}
Define $T_4:\mathbb{R}^2\to\mathbb{R}^3$ by $T_4(x,y)=(x,y,0)$. Then $T_4$ is a linear transformation; that is, for all $u,v\in\mathbb{R}^2$ and all scalars $c\in\mathbb{R}$,
\[
\label{eq:6.u26}
T_4(u+v)=T_4(u)+T_4(v)\quad\text{and}\quad T_4(cu)=c\,T_4(u).
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:6.4}
Let $u=(x_1,y_1)$ and $v=(x_2,y_2)$ be elements of $\mathbb{R}^2$, and let $c\in\mathbb{R}$. Then
\[
\label{eq:6.u27}
T_4(u+v)=T_4(x_1+x_2,\,y_1+y_2)=(x_1+x_2,\,y_1+y_2,\,0)
\]
while
\[
\label{eq:6.u28}
T_4(u)+T_4(v)=(x_1,y_1,0)+(x_2,y_2,0)=(x_1+x_2,\,y_1+y_2,\,0).
\]
Hence $T_4(u+v)=T_4(u)+T_4(v)$. Also,
\[
\label{eq:6.u29}
T_4(cu)=T_4(cx_1,\,cy_1)=(cx_1,\,cy_1,\,0)=c(x_1,y_1,0)=c\,T_4(u).
\]
Therefore $T_4$ satisfies additivity and homogeneity, so $T_4$ is linear.
\end{proof}

