\begin{definition}
\label{def:6.5}
[Matrices]
Let $m,n\in\mathbb{N}$ with $m,n\ge 1$. An \emph{$m\times n$ matrix} over a set $S$ is a family of elements of $S$ indexed by pairs $(i,j)$ with $1\le i\le m$ and $1\le j\le n$, denoted
\[
\label{eq:6.u31}
A=(a_{ij})_{1\le i\le m;\,1\le j\le n},
\]
and displayed as
\[
\label{eq:6.u32}
A = \begin{pmatrix}
 a_{11} & a_{12} & \ldots & a_{1n} \\
 a_{21} & a_{22} & \ldots & a_{2n} \\
 \vdots & \vdots & \ddots & \vdots \\
 a_{m1} & a_{m2} & \ldots & a_{mn}
\end{pmatrix}.
\]
A $1\times n$ matrix is called an \emph{$n$-dimensional row vector}, and an $n\times 1$ matrix is called an \emph{$n$-dimensional column vector}.
\end{definition}

\begin{lemma}
\label{lem:6.2}
Let $T:\mathbb{R}^n\to\mathbb{R}^m$ be a linear transformation. Then there exists a unique matrix $A\in\mathbb{R}^{m\times n}$ such that $T=L_A$, i.e., $Tx=Ax$ for all $x\in\mathbb{R}^n$.
\end{lemma}

\begin{lemma}
\label{lem:6.3}
Let $A$ be an $m\times n$ matrix and let $B$ be an $n\times p$ matrix over the same field. For each matrix $M$, let $L_M$ denote left-multiplication by $M$ on column vectors of compatible size, i.e., $L_M(x)=Mx$. Then, as linear maps $L_B:\Bbb F^p\to\Bbb F^n$ and $L_A:\Bbb F^n\to\Bbb F^m$, one has
\[
\label{eq:6.u42}
L_A\circ L_B = L_{AB} : \Bbb F^p\to\Bbb F^m.
\]
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:6.3}
Let $x\in\Bbb F^p$. Then
\[
\label{eq:6.u43}
(L_A\circ L_B)(x)=L_A(L_B(x))=L_A(Bx)=A(Bx)=(AB)x=L_{AB}(x).
\]
Since the two linear maps agree on all $x\in\Bbb F^p$, $L_A\circ L_B=L_{AB}$.
\end{proof}

