\begin{proposition}
\label{prop:6.6}
Let $T:\mathbb{R}^n\to\mathbb{R}^m$ and $S:\mathbb{R}^p\to\mathbb{R}^n$ be linear transformations. Define $TS:\mathbb{R}^p\to\mathbb{R}^m$ by
\[
\label{eq:6.u44}
(TS)(x)=T(S(x))\quad\text{for all }x\in\mathbb{R}^p.
\]
Then $TS$ is a linear transformation.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:6.6}
Let $x,y\in\mathbb{R}^p$ and $\alpha,\beta\in\mathbb{R}$. Since $S$ is linear,
\[
\label{eq:6.u45}
S(\alpha x+\beta y)=\alpha S(x)+\beta S(y).
\]
Applying $T$ and using linearity of $T$ gives
\[
\label{eq:6.u46}
(TS)(\alpha x+\beta y)=T\bigl(S(\alpha x+\beta y)\bigr)=T\bigl(\alpha S(x)+\beta S(y)\bigr)=\alpha T(S(x))+\beta T(S(y))=\alpha (TS)(x)+\beta (TS)(y).
\]
Therefore $TS$ is linear.
\end{proof}

