\begin{proposition}
\label{prop:6.7}
Let $T:\mathbb{R}^n\to\mathbb{R}^m$ be a linear transformation. Then there exists a constant $M>0$ such that
\[
\label{eq:6.u47}
\|Tx\|\le M\,\|x\|\qquad\text{for all }x\in\mathbb{R}^n.
\]
Consequently, $T$ is continuous on $\mathbb{R}^n$.
\end{proposition}

\begin{definition}
\label{def:6.7}
[Derivative in one variable]
Let $E\subseteq\mathbb{R}$ and let $f:E\to\mathbb{R}$. For $x_0\in E$, the derivative of $f$ at $x_0$ is
\[
\label{eq:6.u52}
f'(x_0):=\lim_{x\to x_0;\, x\in E\setminus\{x_0\}}\frac{f(x)-f(x_0)}{x-x_0},
\]
provided the limit exists.
\end{definition}

\begin{lemma}
\label{lem:6.4}
Let $E\subseteq\mathbb{R}$, let $f:E\to\mathbb{R}$, let $x_0\in E$ be a limit point of $E$, and let $L\in\mathbb{R}$. Then the following statements are equivalent:
\begin{enumerate}
\item[(a)] $f$ is differentiable at $x_0$ and $f'(x_0)=L$, i.e.
\[
\label{eq:6.u53}
\lim_{x\to x_0;\,x\in E\setminus\{x_0\}}\frac{f(x)-f(x_0)}{x-x_0}=L.
\]
\item[(b)]
\[
\label{eq:6.u54}
\lim_{x\to x_0;\,x\in E\setminus\{x_0\}} \frac{\left|f(x)-\bigl(f(x_0)+L(x-x_0)\bigr)\right|}{|x-x_0|}=0.
\]
\end{enumerate}
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:6.4}
(a)$\Rightarrow$(b). Assume $f$ is differentiable at $x_0$ and $f'(x_0)=L$. For $x\in E\setminus\{x_0\}$,
\[
\label{eq:6.u55}
\frac{\left|f(x)-\bigl(f(x_0)+L(x-x_0)\bigr)\right|}{|x-x_0|}
=\left|\frac{f(x)-f(x_0)}{x-x_0}-L\right|.
\]
Taking the limit as $x\to x_0$ with $x\in E\setminus\{x_0\}$ yields $0$ by the definition of derivative.

(b)$\Rightarrow$(a). Assume (b). For $x\in E\setminus\{x_0\}$, the identity above implies
\[
\label{eq:6.u56}
\left|\frac{f(x)-f(x_0)}{x-x_0}-L\right|
=\frac{\left|f(x)-\bigl(f(x_0)+L(x-x_0)\bigr)\right|}{|x-x_0|}.
\]
Taking the limit as $x\to x_0$ with $x\in E\setminus\{x_0\}$ gives
\[
\label{eq:6.u57}
\lim_{x\to x_0;\,x\in E\setminus\{x_0\}}\left|\frac{f(x)-f(x_0)}{x-x_0}-L\right|=0,
\]
so $\displaystyle \lim_{x\to x_0;\,x\in E\setminus\{x_0\}}\frac{f(x)-f(x_0)}{x-x_0}=L$. Hence $f$ is differentiable at $x_0$ and $f'(x_0)=L$.
\end{proof}

