\begin{definition}
\label{def:6.8}
[Differentiability]
Let $E\subseteq\mathbb{R}^n$, let $f:E\to\mathbb{R}^m$, and let $x_0\in E$ be a limit point of $E$. Let $L:\mathbb{R}^n\to\mathbb{R}^m$ be a linear transformation. The function $f$ is \emph{differentiable at $x_0$ with derivative $L$} if
\[
\label{eq:6.u58}
\lim_{x\to x_0;\, x\in E\setminus\{x_0\}} \frac{\|f(x)-\bigl(f(x_0)+L(x-x_0)\bigr)\|}{\|x-x_0\|}=0.
\]
The norm $\|\cdot\|$ denotes the Euclidean norm on $\mathbb{R}^k$ (for any $k$), defined by
\[
\label{eq:6.u59}
\|(x_1,\dots,x_k)\|=\bigl(x_1^2+\cdots+x_k^2\bigr)^{1/2}.
\]
\end{definition}

\begin{proposition}
\label{prop:6.8}
Let $f:\mathbb{R}^2\to\mathbb{R}^2$ be defined by $f(x,y)=(x^2,y^2)$. Then $f$ is differentiable at $x_0=(1,2)$ with derivative $L:\mathbb{R}^2\to\mathbb{R}^2$ given by $L(x,y)=(2x,4y)$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:6.8}
By definition, it suffices to show
\[
\label{eq:6.u60}
\lim_{(x,y)\to(1,2);\,(x,y)\neq(1,2)}\frac{\|f(x,y)-(f(1,2)+L((x,y)-(1,2)))\|}{\|(x,y)-(1,2)\|}=0.
\]
With the change of variables $(x,y)=(1,2)+(a,b)$, this limit equals
\[
\label{eq:6.u61}
\lim_{(a,b)\to(0,0);\,(a,b)\neq(0,0)}\frac{\|f(1+a,2+b)-(f(1,2)+L(a,b))\|}{\|(a,b)\|}.
\]
Substituting $f(1+a,2+b)=((1+a)^2,(2+b)^2)$, $f(1,2)=(1,4)$, and $L(a,b)=(2a,4b)$ gives
\[
\label{eq:6.u62}
\lim_{(a,b)\to(0,0);\,(a,b)\neq(0,0)}\frac{\|((1+a)^2,(2+b)^2)-(1,4)-(2a,4b)\|}{\|(a,b)\|}
=\lim_{(a,b)\to(0,0);\,(a,b)\neq(0,0)}\frac{\|(a^2,b^2)\|}{\|(a,b)\|}.
\]
The quantity $\frac{\|(a^2,b^2)\|}{\|(a,b)\|}$ is nonnegative. Also,
\[
\label{eq:6.u63}
\|(a^2,b^2)\|\le \|(a^2,0)\|+\|(0,b^2)\|=a^2+b^2,
\]
so
\[
\label{eq:6.u64}
0\le \frac{\|(a^2,b^2)\|}{\|(a,b)\|}\le \frac{a^2+b^2}{\sqrt{a^2+b^2}}=\sqrt{a^2+b^2}\xrightarrow[(a,b)\to(0,0)]{}0.
\]
By the squeeze theorem, the limit is $0$, hence $f$ is differentiable at $(1,2)$ with derivative $L$.
\end{proof}

