\begin{lemma}
\label{lem:6.5}
[Uniqueness of derivatives]
Let $E\subseteq\mathbb{R}^n$, let $f:E\to\mathbb{R}^m$, and let $x_0\in E$ be an interior point of $E$. Let $L_1,L_2:\mathbb{R}^n\to\mathbb{R}^m$ be linear transformations. Assume that
\[
\label{eq:6.u65}
\lim_{x\to x_0,\,x\in E}\frac{\|f(x)-f(x_0)-L_1(x-x_0)\|}{\|x-x_0\|}=0
\quad\text{and}\quad
\lim_{x\to x_0,\,x\in E}\frac{\|f(x)-f(x_0)-L_2(x-x_0)\|}{\|x-x_0\|}=0.
\]
Then $L_1=L_2$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:6.5}
Define $A:=L_1-L_2$, which is linear. For $x\in E$ with $x\neq x_0$,
\[
\label{eq:6.u66}
\frac{\|A(x-x_0)\|}{\|x-x_0\|}
\le \frac{\|f(x)-f(x_0)-L_1(x-x_0)\|}{\|x-x_0\|}+\frac{\|f(x)-f(x_0)-L_2(x-x_0)\|}{\|x-x_0\|}.
\]
Taking the limit as $x\to x_0$ with $x\in E$ yields
\[
\label{eq:6.u67}
\lim_{x\to x_0,\,x\in E}\frac{\|A(x-x_0)\|}{\|x-x_0\|}=0.
\]
Let $h\in\mathbb{R}^n$ be arbitrary and nonzero. Since $x_0$ is an interior point of $E$, there exists $r>0$ such that $B(x_0,r)\subseteq E$. For $t\in\mathbb{R}$ with $0<|t|<r\|h\|$, the point $x_0+th$ lies in $E$, and by linearity of $A$,
\[
\label{eq:6.u68}
\frac{\|A((x_0+th)-x_0)\|}{\|(x_0+th)-x_0\|}=
\frac{\|A(th)\|}{\|th\|}=
\frac{\|tA(h)\|}{|t|\,\|h\|}=
\frac{\|A(h)\|}{\|h\|}.
\]
The left-hand side tends to $0$ as $t\to 0$, hence $\|A(h)\|/\|h\|=0$, so $A(h)=0$. Also $A(0)=0$. Therefore $A=0$, i.e. $L_1=L_2$.
\end{proof}

