\begin{definition}
\label{def:6.9}
[Directional derivative]
Let $E\subseteq\mathbb{R}^n$, let $f:E\to\mathbb{R}^m$, let $x_0\in E$ be an interior point of $E$, and let $v\in\mathbb{R}^n$. If the limit
\[
\label{eq:6.u69}
\lim_{\substack{t\to 0\\ t>0,\ x_0+tv\in E}}\frac{f(x_0+tv)-f(x_0)}{t}
\]
exists in $\mathbb{R}^m$, then $f$ is said to be (one-sided) directionally differentiable at $x_0$ in the direction $v$, and the (one-sided) directional derivative of $f$ at $x_0$ in the direction $v$ is defined by
\[
\label{eq:6.u70}
D_v f(x_0):=\lim_{\substack{t\to 0\\ t>0,\ x_0+tv\in E}}\frac{f(x_0+tv)-f(x_0)}{t}.
\]
\end{definition}

\begin{lemma}
\label{lem:6.6}
Let $E\subset\mathbb{R}^n$, let $f:E\to\mathbb{R}^m$, and let $x_0$ be an interior point of $E$. Let $v\in\mathbb{R}^n$. If $f$ is differentiable at $x_0$, with derivative (Jacobian) $f'(x_0)\in\mathbb{R}^{m\times n}$, then the directional derivative of $f$ at $x_0$ in the direction $v$ exists and satisfies
\[
\label{eq:6.u71}
D_v f(x_0)=f'(x_0)v.
\]
\end{lemma}

\begin{theorem}
\label{thm:6.1}
Let $E\subset \mathbb{R}^n$, let $f:E\to \mathbb{R}^m$, let $F\subset E$, and let $x_0\in F$ be an interior point of $F$ (equivalently, there exists $r>0$ such that $B(x_0,r)\subset F$). Assume that for each $j\in\{1,\dots,n\}$ the partial derivative $\frac{\partial f}{\partial x_j}$ exists at every point of $F$ and is continuous at $x_0$. Then $f$ is differentiable at $x_0$, and its derivative $f'(x_0):\mathbb{R}^n\to\mathbb{R}^m$ is the linear map
\[
\label{eq:6.u81}
f'(x_0)(v_1,\dots,v_n)=\sum_{j=1}^n v_j\,\frac{\partial f}{\partial x_j}(x_0),\qquad (v_1,\dots,v_n)\in\mathbb{R}^n.
\]
\end{theorem}

\begin{theorem}
\label{thm:6.2}
Let $F\subseteq\mathbb{R}^n$ be a set and let $f:F\to\mathbb{R}^m$ be a function. Assume that $x_0\in F$ is an interior point of $F$ and that, for each $j\in\{1,\dots,n\}$, the partial derivative $\frac{\partial f}{\partial x_j}$ exists on a neighborhood of $x_0$ contained in $F$ and is continuous at $x_0$. Then for every $v=(v_1,\ldots,v_n)\in\mathbb{R}^n$ the directional derivative
\[
\label{eq:6.u93}
D_v f(x_0):=\lim_{t\to 0}\frac{f(x_0+t v)-f(x_0)}{t}
\]
exists and satisfies
\[
\label{eq:6.u94}
D_v f(x_0)=\sum_{j=1}^n v_j\,\frac{\partial f}{\partial x_j}(x_0).
\]
In particular, if $m=1$ and $\nabla f(x_0):=\Bigl(\frac{\partial f}{\partial x_1}(x_0),\ldots,\frac{\partial f}{\partial x_n}(x_0)\Bigr)$, then
\[
\label{eq:6.u95}
D_v f(x_0)=v\cdot \nabla f(x_0).
\]
\end{theorem}

\begin{definition}
\label{def:6.11}
Let $E\subseteq\mathbb{R}^n$, let $f:E\to\mathbb{R}^m$ with $f=(f_1,\ldots,f_m)$, and let $x_0\in E$ be a point at which all partial derivatives $\frac{\partial f_i}{\partial x_j}(x_0)$ exist. The \emph{derivative matrix} (Jacobian matrix) of $f$ at $x_0$ is the $m\times n$ matrix
\[
\label{eq:6.u105}
Df(x_0):=\left(\frac{\partial f_i}{\partial x_j}(x_0)\right)_{1\le i\le m,\,1\le j\le n}.
\]
\end{definition}

\begin{proposition}
\label{prop:6.9}
Let $E\subseteq\mathbb{R}^n$, let $f:E\to\mathbb{R}^m$, and let $x_0\in E$. Assume that $f$ is differentiable at $x_0$ in the sense that there exists a linear map $f'(x_0):\mathbb{R}^n\to\mathbb{R}^m$ such that
\[
\label{eq:6.u106}
\lim_{h\to 0}\frac{\|f(x_0+h)-f(x_0)-f'(x_0)(h)\|}{\|h\|}=0.
\]
Let $Df(x_0)$ denote the $m\times n$ matrix of partial derivatives of $f$ at $x_0$, so that $f'(x_0)=L_{Df(x_0)}$ under the usual identification between linear maps and matrices. For $v=(v_1,\dots,v_n)\in\mathbb{R}^n$ (viewed as a row vector) let $v^T$ be its transpose. Then the directional derivative $D_v f(x_0)$ exists and
\[
\label{eq:6.u107}
(D_v f(x_0))^T = Df(x_0)\,v^T.
\]
Equivalently,
\[
\label{eq:6.u108}
D_v f(x_0)=f'(x_0)(v)=\sum_{j=1}^n v_j\,\frac{\partial f}{\partial x_j}(x_0).
\]
\end{proposition}

\begin{theorem}
\label{thm:6.3}
(Several variable calculus chain rule) Let $E\subseteq\mathbb{R}^n$ and $F\subseteq\mathbb{R}^m$. Let $f:E\to F$ and $g:F\to\mathbb{R}^p$. Let $x_0\in E$ be an interior point of $E$, and assume that $f$ is differentiable at $x_0$. Assume also that $f(x_0)$ is an interior point of $F$ and that $g$ is differentiable at $f(x_0)$. Then $g\circ f$ is differentiable at $x_0$, and its derivative is the linear map
\[
\label{eq:6.u115}
(g\circ f)'(x_0)=g'(f(x_0))\,f'(x_0),
\]
where the right-hand side denotes composition of the linear maps $f'(x_0):\mathbb{R}^n\to\mathbb{R}^m$ and $g'(f(x_0)):\mathbb{R}^m\to\mathbb{R}^p$.
\end{theorem}

\begin{theorem}
\label{thm:6.4}
[Matrix form of the chain rule]
Let $E\subseteq\mathbb{R}^n$ and $F\subseteq\mathbb{R}^m$. Let $f:E\to\mathbb{R}^m$ and $g:F\to\mathbb{R}^p$. Assume that $f$ is differentiable at $x_0\in E$ and that $g$ is differentiable at $y_0=f(x_0)\in F$. Then $g\circ f$ is differentiable at $x_0$, and its derivative matrix satisfies
\[
\label{eq:6.u127}
D(g\circ f)(x_0)=Dg(f(x_0))\,Df(x_0).
\]
\end{theorem}

\begin{proposition}
\label{prop:6.10}
[Product rule for gradients]
Let $f,g:\mathbb{R}^n\to\mathbb{R}$ be differentiable at a point $x\in\mathbb{R}^n$. Then the product $h=fg$ is differentiable at $x$ and
\[
\label{eq:6.u136}
\nabla(fg)(x)=g(x)\,\nabla f(x)+f(x)\,\nabla g(x).
\]
If $f$ and $g$ are differentiable on $\mathbb{R}^n$, then $fg$ is differentiable on $\mathbb{R}^n$ and the identity holds for all $x\in\mathbb{R}^n$.
\end{proposition}

\begin{proposition}
\label{prop:6.11}
[Derivative of a linear map composed with a differentiable map]
Let $E\subseteq \mathbb{R}^k$, let $f:E\to \mathbb{R}^n$ be differentiable at $x_0\in E$, and let $T:\mathbb{R}^n\to \mathbb{R}^m$ be linear. Define $Tf:E\to \mathbb{R}^m$ by $(Tf)(x)=T(f(x))$. Then $Tf$ is differentiable at $x_0$, and
\[
\label{eq:6.u143}
D(Tf)(x_0)=T\circ Df(x_0),
\]
where $Df(x_0):\mathbb{R}^k\to \mathbb{R}^n$ is the derivative of $f$ at $x_0$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:6.11}
Since $f$ is differentiable at $x_0$, there exists a linear map $A=Df(x_0):\mathbb{R}^k\to \mathbb{R}^n$ and a function $r:E\to \mathbb{R}^n$ such that
\[
\label{eq:6.u144}
f(x)=f(x_0)+A(x-x_0)+r(x)\quad\text{and}\quad \lim_{x\to x_0}\frac{\|r(x)\|}{\|x-x_0\|}=0.
\]
Applying the linear map $T$ gives
\[
\label{eq:6.u145}
T(f(x))=T(f(x_0))+T\bigl(A(x-x_0)\bigr)+T(r(x)).
\]
Let $s(x)=T(r(x))$. Then $s:E\to \mathbb{R}^m$ and, using continuity of linear maps, there exists $C\ge 0$ such that $\|T(v)\|\le C\|v\|$ for all $v\in\mathbb{R}^n$. Hence
\[
\label{eq:6.u146}
\frac{\|s(x)\|}{\|x-x_0\|}=\frac{\|T(r(x))\|}{\|x-x_0\|}\le C\,\frac{\|r(x)\|}{\|x-x_0\|}\xrightarrow[x\to x_0]{}0.
\]
Therefore $Tf$ is differentiable at $x_0$ with derivative equal to the linear map $T\circ A=T\circ Df(x_0)$.
\end{proof}

