\begin{proposition}
\label{prop:6.12}
[Chain rule along a differentiable curve]
Let $f:\mathbb{R}^n\to\mathbb{R}^m$ be differentiable, and let $x_j:\mathbb{R}\to\mathbb{R}$ be differentiable for $j=1,\dots,n$. Define $\gamma:\mathbb{R}\to\mathbb{R}^n$ by $\gamma(t)=(x_1(t),\dots,x_n(t))$. Then the composition $f\circ\gamma:\mathbb{R}\to\mathbb{R}^m$ is differentiable, and for every $t\in\mathbb{R}$,
\[
\label{eq:6.u147}
\frac{d}{dt}f(\gamma(t))=Df(\gamma(t))\,\gamma'(t)=\sum_{j=1}^n x_j'(t)\,\frac{\partial f}{\partial x_j}(\gamma(t)).
\]
\end{proposition}

\begin{definition}
\label{def:6.12}
(Twice continuous differentiability) Let $E\subseteq\mathbb{R}^n$ be open and let $f:E\to\mathbb{R}^m$. The function $f$ is called \emph{twice continuously differentiable} (or of class $C^2$) on $E$ if the following hold:
\begin{enumerate}
\item $f$ is continuously differentiable on $E$, i.e., all first-order partial derivatives $\frac{\partial f}{\partial x_i}:E\to\mathbb{R}^m$ exist and are continuous for $i=1,\dots,n$.
\item For each $i=1,\dots,n$, the map $\frac{\partial f}{\partial x_i}$ is continuously differentiable on $E$.
\end{enumerate}
\end{definition}

\begin{theorem}
\label{thm:6.5}
[Clairaut's theorem]
Let $E\subseteq\mathbb{R}^n$ be open, and let $f:E\to\mathbb{R}^m$ be of class $C^2$ on $E$. Then for every $x_0\in E$, every component $f_\ell$ of $f$ $(1\le \ell\le m)$, and all indices $1\le i,j\le n$, the mixed second partial derivatives exist at $x_0$ and satisfy
\[
\label{eq:6.u155}
\frac{\partial^2 f_\ell}{\partial x_j\,\partial x_i}(x_0)=\frac{\partial^2 f_\ell}{\partial x_i\,\partial x_j}(x_0).
\]
Equivalently, as a map $E\to\mathbb{R}^m$,
\[
\label{eq:6.u156}
\frac{\partial}{\partial x_j}\left(\frac{\partial f}{\partial x_i}\right)(x_0)=\frac{\partial}{\partial x_i}\left(\frac{\partial f}{\partial x_j}\right)(x_0).
\]
\end{theorem}

\begin{definition}
\label{def:6.13}
[Contraction and strict contraction]
Let $(X,d)$ be a metric space and let $f\colon X\to X$.
\begin{enumerate}
\item The map $f$ is called a \emph{contraction} if for all $x,y\in X$ one has
\[
\label{eq:6.u170}
d\bigl(f(x),f(y)\bigr)\le d(x,y).
\]
\item The map $f$ is called a \emph{strict contraction} if there exists a constant $c$ with $0<c<1$ such that for all $x,y\in X$ one has
\[
\label{eq:6.u171}
d\bigl(f(x),f(y)\bigr)\le c\,d(x,y).
\]
Any such constant $c$ is called a \emph{contraction constant} of $f$.
\end{enumerate}
\end{definition}

\begin{definition}
\label{def:6.14}
\textup{(Fixed point)} Let $X$ be a set and let $f\colon X\to X$ be a map. An element $x\in X$ is called a \emph{fixed point} of $f$ if $f(x)=x$.
\end{definition}

\begin{theorem}
\label{thm:6.6}
[Banach fixed-point theorem]
Let $(X,d)$ be a nonempty complete metric space, and let $f\colon X\to X$ satisfy the contraction condition: there exists a constant $c\in(0,1)$ such that
\[
\label{eq:6.u172}
d\bigl(f(x),f(y)\bigr)\le c\,d(x,y)\qquad\text{for all }x,y\in X.
\]
Then there exists a unique point $x^*\in X$ such that $f(x^*)=x^*$. Moreover, for every $x_0\in X$, the sequence $(x_n)_{n\ge 0}$ defined by $x_{n+1}=f(x_n)$ for $n\ge 0$ converges in $(X,d)$ to $x^*$.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:6.6}
\textit{Step 1: Existence of a limit point of the iterates.}
Fix $x_0\in X$ and define $x_{n+1}=f(x_n)$ for $n\ge 0$. For $n\ge 0$,
\[
\label{eq:6.u173}
d(x_{n+1},x_n)=d\bigl(f(x_n),f(x_{n-1})\bigr)\le c\,d(x_n,x_{n-1}).
\]
By induction this yields
\[
\label{eq:6.u174}
d(x_{n+1},x_n)\le c^n d(x_1,x_0)\qquad\text{for all }n\ge 0.
\]
For integers $m>n$ the triangle inequality gives
\[
\label{eq:6.u175}
d(x_m,x_n)\le \sum_{k=n}^{m-1} d(x_{k+1},x_k)\le \sum_{k=n}^{m-1} c^k d(x_1,x_0)
\le \frac{c^n}{1-c}\,d(x_1,x_0).
\]
Since $c\in(0,1)$, the right-hand side tends to $0$ as $n\to\infty$, uniformly in $m>n$. Hence $(x_n)$ is a Cauchy sequence in $X$. Completeness of $(X,d)$ implies that there exists $x^*\in X$ such that $x_n\to x^*$.

\textit{Step 2: The limit is a fixed point.}
For each $n\ge 0$,
\[
\label{eq:6.u176}
d\bigl(f(x^*),x^*\bigr)\le d\bigl(f(x^*),f(x_n)\bigr)+d(x_{n+1},x^*)\le c\,d(x^*,x_n)+d(x_{n+1},x^*).
\]
Letting $n\to\infty$ and using $x_n\to x^*$ gives $d\bigl(f(x^*),x^*\bigr)=0$, hence $f(x^*)=x^*$.

\textit{Step 3: Uniqueness.}
If $y^*\in X$ is another fixed point, then
\[
\label{eq:6.u177}
d(x^*,y^*)=d\bigl(f(x^*),f(y^*)\bigr)\le c\,d(x^*,y^*).
\]
Since $c<1$, this implies $(1-c)d(x^*,y^*)\le 0$, hence $d(x^*,y^*)=0$ and $x^*=y^*$.

\textit{Step 4: Convergence for every initial point.}
The preceding construction applies to any $x_0\in X$ and produces a limit $x^*$ which is a fixed point of $f$. By uniqueness of the fixed point, this limit must be the same $x^*$ for every $x_0$. Therefore $x_n\to x^*$ for every choice of $x_0\in X$.
\end{proof}

