\begin{theorem}
\label{thm:6.7}
[Contraction mapping theorem]
Let $(X,d)$ be a metric space and let $f\colon X\to X$ be a strict contraction, i.e., there exists a constant $c\in[0,1)$ such that
\[
\label{eq:6.u178}
d\bigl(f(x),f(y)\bigr)\le c\,d(x,y)\qquad\text{for all }x,y\in X.
\]
Then $f$ has at most one fixed point. If, in addition, $X$ is non-empty and complete, then $f$ has exactly one fixed point.
\end{theorem}

\begin{theorem}
\label{thm:6.8}
[Hairy ball theorem (fixed point/anti-fixed point alternative)]
Let $S^2:=\{(x,y,z)\in\mathbb{R}^3 : x^2+y^2+z^2=1\}$. If $f:S^2\to S^2$ is continuous, then there exists $x\in S^2$ such that either $f(x)=x$ or $f(x)=-x$.
\end{theorem}

\begin{lemma}
\label{lem:6.7}
Let $r>0$ and let $B(0,r)=\{x\in\mathbb{R}^n:\|x\|<r\}$. Suppose $g:B(0,r)\to\mathbb{R}^n$ satisfies $g(0)=0$ and
\[
\label{eq:6.u194}
\|g(x)-g(y)\|\le \tfrac12\|x-y\|\qquad\text{for all }x,y\in B(0,r).
\]
Define $f:B(0,r)\to\mathbb{R}^n$ by $f(x)=x+g(x)$. Then $f$ is injective, and
\[
\label{eq:6.u195}
B(0,r/2)\subseteq f(B(0,r)).
\]
\end{lemma}

\begin{proposition}
\label{prop:6.13}
Let $f:[a,b]\to[a,b]$ be differentiable.
If $|f'(x)|\le 1$ for all $x\in[a,b]$, then for all $x,y\in[a,b]$,
\[
\label{eq:6.u200}
|f(x)-f(y)|\le |x-y|.
\]
In particular, $f$ is a (non-expanding) contraction on $[a,b]$ with respect to the metric $d(x,y)=|x-y|$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:6.13.1}
Let $x,y\in[a,b]$. If $x=y$ the inequality is trivial. If $x\ne y$, the mean value theorem gives a point $\xi$ between $x$ and $y$ such that
\[
\label{eq:6.u202}
f(x)-f(y)=f'(\xi)(x-y).
\]
Taking absolute values and using $|f'(\xi)|\le 1$ yields
\[
\label{eq:6.u203}
|f(x)-f(y)|=|f'(\xi)|\,|x-y|\le |x-y|.
\]

