\begin{proposition}
\label{prop:6.14}
Let $f:[a,b]\to\mathbb{R}$ be differentiable. Assume that $f$ is a contraction on $[a,b]$ with respect to $d(x,y)=|x-y|$, i.e.,
\[
\label{eq:6.u205}
|f(x)-f(y)|\le |x-y|\quad\text{for all }x,y\in[a,b].
\]
Then $|f'(x)|\le 1$ for all $x\in[a,b]$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:6.14}
Fix $x\in[a,b]$. For any $h\in\mathbb{R}$ such that $x+h\in[a,b]$, the contraction property gives
\[
\label{eq:6.u206}
|f(x+h)-f(x)|\le |h|.
\]
If $h\ne 0$, dividing by $|h|$ yields
\[
\label{eq:6.u207}
\left|\frac{f(x+h)-f(x)}{h}\right|\le 1.
\]
Since $f$ is differentiable at $x$, letting $h\to 0$ through values with $x+h\in[a,b]$ gives
\[
\label{eq:6.u208}
|f'(x)|=\left|\lim_{h\to 0}\frac{f(x+h)-f(x)}{h}\right|\le 1.
\]
Because $x$ was arbitrary, the inequality holds for all $x\in[a,b]$.
\end{proof}

