Let $(X,d)$ be a metric space and let $f\colon X\to X$ be a contraction, i.e., there exists a constant $c\in[0,1)$ such that
\[
\label{eq:6.u209}
d\bigl(f(x),f(y)\bigr)\le c\,d(x,y)\qquad\text{for all }x,y\in X.
\]
Then $f$ is (Lipschitz and hence) continuous on $X$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:6.15}
Fix $x\in X$ and let $\varepsilon>0$. Choose $\delta=\varepsilon/c$ if $c>0$, and choose any $\delta>0$ if $c=0$. If $y\in X$ satisfies $d(x,y)<\delta$, then
\[
\label{eq:6.u210}
d\bigl(f(x),f(y)\bigr)\le c\,d(x,y)<c\,\delta\le \varepsilon.
\]
This verifies continuity of $f$ at $x$. Since $x$ was arbitrary, $f$ is continuous on $X$.
\end{proof}

