\begin{theorem}
\label{thm:6.9}
[Inverse function theorem in one variable]
Let $f:\mathbb{R}\to\mathbb{R}$ be injective and differentiable on an open interval $I\subseteq\mathbb{R}$. Let $x_0\in I$ and set $y_0=f(x_0)$. Assume that $f'(x_0)\neq 0$ and that the inverse function $f^{-1}$ is defined on an open interval $J$ containing $y_0$ with $f^{-1}(y)=x$ for all $y=f(x)$ with $x\in I$. Then $f^{-1}$ is differentiable at $y_0$ and
\[
\label{eq:6.u217}
(f^{-1})'(y_0)=\frac{1}{f'(x_0)}.
\]
\end{theorem}

\begin{definition}
\label{def:6.15}
[Local invertibility]
Let $f:\mathbb{R}\to\mathbb{R}$ and let $x_0\in\mathbb{R}$. The function $f$ is \emph{locally invertible near $x_0$} if there exist open intervals $I\subseteq\mathbb{R}$ and $J\subseteq\mathbb{R}$ with $x_0\in I$ and $f(x_0)\in J$ such that the restriction $f\vert_I:I\to J$ is a bijection.
\end{definition}

\begin{lemma}
\label{lem:6.8}
Let $T:\mathbb{R}^n\to\mathbb{R}^n$ be a linear transformation that is invertible (i.e., bijective), and let $T^{-1}:\mathbb{R}^n\to\mathbb{R}^n$ denote its inverse map. Then $T^{-1}$ is linear.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:6.8}
Let $u,v\in\mathbb{R}^n$ and $a,b\in\mathbb{R}$. Since $T$ is surjective, there exist $x,y\in\mathbb{R}^n$ such that $u=T(x)$ and $v=T(y)$. Then
\[
\label{eq:6.u225}
T^{-1}(au+bv)=T^{-1}(aT(x)+bT(y))=T^{-1}(T(ax+by))=ax+by.
\]
Also $T^{-1}(u)=T^{-1}(T(x))=x$ and $T^{-1}(v)=T^{-1}(T(y))=y$, so
\[
\label{eq:6.u226}
ax+by=aT^{-1}(u)+bT^{-1}(v).
\]
Therefore $T^{-1}(au+bv)=aT^{-1}(u)+bT^{-1}(v)$ for all $u,v$ and $a,b$, which proves that $T^{-1}$ is linear.
\end{proof}

