\begin{theorem}
\label{thm:6.10}
[Inverse Function Theorem]
Let $E\subseteq\mathbb{R}^n$ be open, and let $f:E\to\mathbb{R}^n$ be continuously differentiable on $E$. Assume that $x_0\in E$ and that the derivative $f'(x_0):\mathbb{R}^n\to\mathbb{R}^n$ is invertible. Then there exist open sets $U\subseteq E$ and $V\subseteq\mathbb{R}^n$ such that $x_0\in U$, $f(x_0)\in V$, and the restriction $f|_U:U\to V$ is a bijection. In particular, an inverse map $f^{-1}:V\to U$ exists.

Moreover, $f^{-1}$ is differentiable at $y_0:=f(x_0)$, and
\[
\label{eq:6.u227}
(f^{-1})'(y_0)=\bigl(f'(x_0)\bigr)^{-1}.
\]
\end{theorem}

\begin{definition}
\label{def:6.16}
[Graph of a function]
Let $f: \mathbb{R}^n \to \mathbb{R}$. The \emph{graph} of $f$ is the subset
\[
\label{eq:6.u244}
\operatorname{graph}(f) := \{(x, f(x)) : x \in \mathbb{R}^n\} \subseteq \mathbb{R}^{n+1}.
\]
\end{definition}

\begin{definition}
\label{def:6.17}
[Vertical line test]
A subset $S \subseteq \mathbb{R}^2$ is the graph of a function $f: \mathbb{R} \to \mathbb{R}$ if and only if for every $x \in \mathbb{R}$ there exists a unique $y \in \mathbb{R}$ such that $(x,y) \in S$.
\end{definition}

\begin{definition}
\label{def:6.18}
[Hypersurface defined by an equation]
Let $g: \mathbb{R}^n \to \mathbb{R}$. The \emph{hypersurface} (level set) defined by $g$ is
\[
\label{eq:6.u245}
Z(g) := \{x \in \mathbb{R}^n : g(x)=0\}.
\]
\end{definition}

\begin{theorem}
\label{thm:6.11}
[Implicit function theorem]
Let $E\subset\mathbb{R}^n$ be open, let $f:E\to\mathbb{R}$ be continuously differentiable, and let $y=(y_1,\ldots,y_n)\in E$ satisfy $f(y)=0$ and $\frac{\partial f}{\partial x_n}(y)\neq 0$. Then there exist an open set $U\subset\mathbb{R}^{n-1}$ containing $y'=(y_1,\ldots,y_{n-1})$, an open set $V\subset E$ containing $y$, and a unique function $g:U\to\mathbb{R}$ such that $g(y')=y_n$ and
\[
\label{eq:6.u246}
\{x\in V: f(x)=0\}=\{(x',g(x')):x'\in U\},
\]
where $x'=(x_1,\ldots,x_{n-1})$. Moreover, $g$ is continuously differentiable on $U$, and for every $x'\in U$ and every $1\le j\le n-1$,
\[
\label{eq:6.u247}
\frac{\partial g}{\partial x_j}(x')=-\frac{\frac{\partial f}{\partial x_j}(x',g(x'))}{\frac{\partial f}{\partial x_n}(x',g(x'))}.
\]
\end{theorem}

proof:
\begin{proof}
\label{prf:prop:6.17}
Define $F:V\to\mathbb{R}$ by $F(x_1,\ldots,x_{n-1})=f(x_1,\ldots,x_{n-1},g(x_1,\ldots,x_{n-1}))$. By assumption, $F\equiv 0$ on $V$, hence $\frac{\partial F}{\partial x_j}=0$ on $V$ for each $j\in\{1,\ldots,n-1\}$. Since $f$ and $g$ are differentiable, the chain rule gives, for each $(x_1,\ldots,x_{n-1})\in V$,
\[
\label{eq:6.u262}
\frac{\partial F}{\partial x_j}(x_1,\ldots,x_{n-1})=
\frac{\partial f}{\partial x_j}\bigl(x_1,\ldots,x_{n-1},g(x_1,\ldots,x_{n-1})\bigr)
+\frac{\partial f}{\partial x_n}\bigl(x_1,\ldots,x_{n-1},g(x_1,\ldots,x_{n-1})\bigr)\,\frac{\partial g}{\partial x_j}(x_1,\ldots,x_{n-1}).
\]
Setting this equal to $0$ yields the stated identity. If additionally $\frac{\partial f}{\partial x_n}\bigl(x_1,\ldots,x_{n-1},g(x_1,\ldots,x_{n-1})\bigr)\neq 0$ at a point, solving the identity for $\frac{\partial g}{\partial x_j}$ gives the displayed quotient formula.
\end{proof}

